class Solution {
public:
    TreeNode* replaceValueInTree(TreeNode* root) {
        if (!root) return root;
        vector<long long> levelSum;
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            int sz = (int)q.size();
            long long s = 0;
            for (int i = 0; i < sz; i++) {
                TreeNode* node = q.front(); q.pop();
                s += node->val;
                if (node->left)  q.push(node->left);
                if (node->right) q.push(node->right);
            }
            levelSum.push_back(s);
        }
        root->val = 0;
        q.push(root);
        int depth = 0;
        while (!q.empty()) {
            int sz = (int)q.size();
            for (int i = 0; i < sz; i++) {
                TreeNode* node = q.front(); q.pop();
                long long childSum = 0;
                if (node->left)  childSum += node->left->val;
                if (node->right) childSum += node->right->val;
                long long cousinSum = (depth + 1 < (int)levelSum.size())
                                      ? levelSum[depth + 1] - childSum
                                      : 0;
                if (node->left) {
                    node->left->val = (int)cousinSum;
                    q.push(node->left);
                }
                if (node->right) {
                    node->right->val = (int)cousinSum;
                    q.push(node->right);
                }
            }
            depth++;
        }
        return root;
    }
};
